def dedup(items):
    out = []
    seen = []
    for it in items:
        dup = False
        for existing in seen:
            try:
                same_type = type(existing) is type(it)
                if same_type and existing == it:
                    dup = True
                    break
            except TypeError:
                # incomparable types -> treat as distinct
                continue
        if not dup:
            seen.append(it)
            out.append(it)
    return out

